          "exaltPlanet": "♄",
          "exaltText": "省一分錢就是一分錢。細節是途徑，通往物質層面的成功。\n若要在物質層面取得成功，取決於細節的展現。",
          "detrimentPlanet": "☿",
          "detrimentText": "成功來自技巧，而非紀律。\n完成必要的細節才能成功，這是天賦，而非紀律。",
          "mechanism": "【6爻·屋頂冷眼旁觀與休息日】卦象頂點與過渡期，宇宙法定休整日，大眾體感易疲倦，適合抽離、冷靜評估整個週期。",
